/**
 * SDK إدارة المستخدمين (البوابة التقنية — وحدة إدارة المستخدمين)
 *  · list: RPC آمنة تتحقق من الدور على الخادم
 *  · setUserRole: RPC مع تدقيق إلزامي؛ IT تستطيع تعديل أدوارها الذاتية مع حماية آخر حساب IT
 *  · updateEmployeeProfile: RPC set_employee_profile (تعديل بيانات الموظف المرتبط)
 *  · create / updateEmail / setBanned / resetPassword: Edge Function admin-users
 *    (عمليات auth تتطلب admin API عبر service_role — لا يلمسه العميل أبداً)
 */
import { sdkGuard, sdkVoid, supabase } from './client'
import { SDKError } from '@lib/errors/SDKError'
import type { Role } from '@lib/constants/roles.constants'

/**
 * الأدوار الحساسة — القائمة المرجعية صارت جدولاً على الخادم (public.sensitive_roles، الجولة ٢).
 * هذا الثابت للعرض والتحديث المتفائل فقط، ويطابقه اختبار عقد مع بذرة الترحيل.
 * الحكم النهائي في الخادم: app.is_sensitive_role(p_role).
 */
export const SENSITIVE_ROLES: readonly Role[] = [
  'super_admin',
  'executive_director',
  'deputy_director',
  'finance_officer',
  'admin_ops',
  'field_ops',
  'it_admin',
  'ops_room_manager',
  'ops_room',
]

export interface RoleGrantRequest {
  id: string
  target_user: string
  target_email: string | null
  target_name: string | null
  role: string
  role_label: string | null
  is_grant: boolean
  status: 'pending' | 'approved' | 'rejected' | 'cancelled'
  requested_by: string
  requested_by_name: string | null
  requested_at: string
  decided_by: string | null
  decided_at: string | null
  note: string | null
}

export interface PlatformUser {
  id: string
  email: string | null
  created_at: string
  last_sign_in_at: string | null
  /** حالة الحساب (auth ban) — null يعني مفعّلاً */
  banned_until: string | null
  roles: Role[]
  /** بيانات سجل الموظف المرتبط (null إن لم يُربط) */
  employee_id: string | null
  employee_name: string | null
  employee_number: string | null
  phone: string | null
  job_title: string | null
  department_id: string | null
  department_name: string | null
}

export interface CreateUserInput {
  email: string
  password: string
  full_name: string
  role: Role
  employee_number?: string
  department_id?: string
  job_title?: string
  /** إسناد مسؤول القسم (فقط مع role = department_manager) */
  manager_shift?: string
  manager_sectors?: number[]
  garage_parent_sector?: string
  /** 00158: حساب متعهد — مسؤول القسم المسؤول ومنطقته (اختيارية إن كان للمسؤول منطقة واحدة) */
  contractor_manager_id?: string
  contractor_sector_id?: number | null
  /** 00160: مسؤول القاطع — القواطع الأم */
  sector_manager_parent_sectors?: string[]
}

/** تعديل بيانات الموظف المرتبط بمستخدم (ينشئ السجل إن لم يوجد) */
export interface UpdateEmployeeProfileInput {
  user_id: string
  full_name: string
  phone?: string | null
  job_title?: string | null
  department_id?: string | null
  employee_number?: string | null
}

export const users = {
  async list(searchQuery?: string): Promise<PlatformUser[]> {
    return sdkGuard(
      supabase.rpc('list_platform_users', { p_query: searchQuery ?? null }),
    ) as Promise<PlatformUser[]>
  },

  /** منح (grant) أو سحب (revoke) دور — الخادم يدقق ويؤرشف
   *  V-36: الأدوار الحساسة لا تُنفَّذ فوراً؛ تُنشئ طلب موافقة للمدير المفوض.
   *  تُعيد `{ pending: true }` كي تُظهر الواجهة «قيد موافقة المدير المفوض» بدل «ممنوح». */
  async setUserRole(userId: string, role: Role, grant: boolean): Promise<{ pending: boolean }> {
    await sdkVoid(
      supabase.rpc('set_user_role', {
        p_user_id: userId,
        p_role: role,
        p_grant: grant,
      }),
    )
    if (!SENSITIVE_ROLES.includes(role)) return { pending: false }
    const rows = (await sdkGuard(
      supabase.rpc('role_grant_requests_list', { p_user_id: userId } as never),
    )) as Array<{ role: string; is_grant: boolean; status: string }>
    return { pending: rows.some((r) => r.role === role && r.is_grant === grant && r.status === 'pending') }
  },

  /** طلبات منح/سحب الأدوار الحساسة (للعرض في شاشة المستخدم) */
  async roleGrantRequests(userId: string): Promise<RoleGrantRequest[]> {
    return sdkGuard(
      supabase.rpc('role_grant_requests_list', { p_user_id: userId } as never),
    ) as Promise<RoleGrantRequest[]>
  },

  /** تعديل بيانات الموظف المرتبط — RPC آمنة تُدقَّن على الخادم (وتنشئ السجل إن لم يوجد) */
  async updateEmployeeProfile(input: UpdateEmployeeProfileInput): Promise<void> {
    await sdkVoid(
      supabase.rpc('set_employee_profile', {
        p_user_id: input.user_id,
        p_full_name: input.full_name,
        p_phone: input.phone ?? null,
        p_job_title: input.job_title ?? null,
        p_department_id: input.department_id ?? null,
        p_employee_number: input.employee_number ?? null,
      }),
    )
  },

  async garageProfileForUser(userId: string): Promise<string | null> {
    const data = await sdkGuard(supabase.rpc('garage_profile_for_user', { p_user_id: userId }))
    return typeof data === 'string' && data.length > 0 ? data : null
  },

  async saveGarageProfile(userId: string, parentSector: string): Promise<void> {
    await sdkVoid(
      supabase.rpc('garage_profile_save', {
        p_user_id: userId,
        p_parent_sector: parentSector,
      }),
    )
  },

  async create(input: CreateUserInput): Promise<{ user_id: string }> {
    return invokeAdmin<{ user_id: string }>({ action: 'create', ...input })
  },

  /** تعطيل/تفعيل حساب (الخادم يمنع تعطيل الذات) */
  async setBanned(userId: string, banned: boolean): Promise<void> {
    await invokeAdmin({ action: 'set_ban', user_id: userId, banned })
  },

  /** إعادة تعيين كلمة مرور مستخدم */
  async resetPassword(userId: string, password: string): Promise<void> {
    await invokeAdmin({ action: 'reset_password', user_id: userId, password })
  },

  /** تغيير بريد مستخدم بواسطة IT، بما فيه بريد حسابها */
  async updateEmail(userId: string, email: string): Promise<void> {
    await invokeAdmin({ action: 'update_email', user_id: userId, email })
  },
}

/** نداء موحّد لـ admin-users مع رسائل عربية آمنة */
async function invokeAdmin<T>(body: Record<string, unknown>): Promise<T> {
  const { data, error } = await supabase.functions.invoke<T>('admin-users', { body })
  if (error) throw await toAdminError(error)
  if (!data) {
    throw new SDKError('استجابة غير متوقعة من خدمة إدارة المستخدمين', 'ADMIN_USERS_EMPTY')
  }
  return data
}

/**
 * استخراج كود خطأ الخادم: FunctionsHttpError يحمل Response غير المقروء
 * في error.context (لا يملك code) — نقرأ { error: 'CODE' } من الجسم.
 */
async function toAdminError(error: unknown): Promise<SDKError> {
  let code = (error as { code?: string }).code ?? ''
  if (!code) {
    const context = (error as { context?: Response }).context
    if (context && typeof context.json === 'function') {
      try {
        const body = (await context.json()) as { error?: string }
        code = String(body.error ?? '')
      } catch {
        /* جسم غير JSON — نستخدم الرسالة العامة */
      }
    }
  }
  const message = ERROR_MESSAGES[code] ?? 'فشلت العملية — حاول مجدداً'
  return new SDKError(message, code || 'ADMIN_USERS_FAILED', error)
}

